import type {ToolDefinition} from '../../types/ai.js';
import Ajv, {type ValidateFunction} from 'ajv';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

function describeValidationError(
  error: {instancePath?: string; dataPath?: string; keyword?: string; params?: Record<string, unknown>} | undefined
): string {
  const instancePath = error?.instancePath ?? error?.dataPath ?? '';
  const path = instancePath
    ? instancePath.startsWith('/')
      ? instancePath.slice(1).split('/').join('.')
      : instancePath.replace(/^\./, '').replace(/[.[\]"]/g, '.')
    : 'input';
  if (error?.keyword === 'required') {
    const missingProperty = String(error.params?.missingProperty ?? 'property');
    const missingPath = path === 'input' ? missingProperty : `${path}.${missingProperty}`;
    return `${missingPath} is required`;
  }
  if (error?.keyword === 'type') return `${path} must be ${String(error.params?.type ?? 'the declared type')}`;
  if (error?.keyword === 'enum') return `${path} must be an allowed enum value`;
  return `${path} is invalid (${error?.keyword ?? 'schema constraint'})`;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly ajv = new Ajv({strict: false, validateFormats: false} as never);
  private readonly dynamicValidators = new WeakMap<object, ValidateFunction>();
  private readonly tools = new Map<string, StoredTool>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validator = this.ajv.compile(resolved.inputSchema);
      } catch (error) {
        const detail = error instanceof Error ? error.message : String(error);
        throw new Error(`Invalid inputSchema for tool ${resolved.name}: ${detail}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Rejects schema-invalid input as a ToolResponse; only an unknown tool name throws (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    let validator = tool.validator;
    if (!validator) {
      validator =
        this.dynamicValidators.get(definition.inputSchema) ?? this.compileDynamicSchema(definition.inputSchema);
    }
    if (!validator(input)) {
      const error = validator.errors?.[0] as
        {instancePath?: string; dataPath?: string; keyword?: string; params?: Record<string, unknown>} | undefined;
      const detail = describeValidationError(error);
      return {result: `Invalid input for ${name}: ${detail}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private compileDynamicSchema(schema: ToolDefinition['inputSchema']): ValidateFunction {
    const validator = this.ajv.compile(schema);
    this.dynamicValidators.set(schema, validator);
    return validator;
  }
}
import {ToolRegistry} from './registry.js';
import Ajv from 'ajv';
import {jest} from '@jest/globals';
import {setLogger, type Logger} from '../../shared/logger.js';

const locationInputSchema = {
  type: 'object',
  properties: {location: {type: 'string'}},
  required: ['location'],
};

describe('ToolRegistry', () => {
  afterEach(() => {
    setLogger();
    jest.restoreAllMocks();
  });

  it('rejects missing required input', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: locationInputSchema,
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('weather', {});

    expect({
      namesRequiredProperty: /location.*required|required.*location/i.test(response.result),
      executorCalls,
    }).toEqual({namesRequiredProperty: true, executorCalls: 0});
  });

  it('names the full path of a missing nested required property', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {
            location: {
              type: 'object',
              properties: {city: {type: 'string'}},
              required: ['city'],
            },
          },
          required: ['location'],
        },
      },
      async () => 'sunny'
    );

    const response = await registry.execute('weather', {location: {}});

    expect(response.result).toMatch(/location\.city.*required|required.*location\.city/i);
  });

  it('rejects a wrong type without exposing its value in the response or logs', async () => {
    const registry = new ToolRegistry();
    const identifyingValue = 'private-user@example.com';
    let executorCalls = 0;
    const logLines: string[] = [];
    const testLogger: Logger = {
      debug: (_category, message, fields) => logLines.push(`${message} ${JSON.stringify(fields)}`),
      info: (_category, message, fields) => logLines.push(`${message} ${JSON.stringify(fields)}`),
      warn: (_category, message, fields) => logLines.push(`${message} ${JSON.stringify(fields)}`),
      error: (_category, message, fields) => logLines.push(`${message} ${JSON.stringify(fields)}`),
    };
    setLogger(testLogger);
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'number'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('weather', {location: identifyingValue as unknown as number});
    expect({
      namesPath: response.result.includes('location'),
      namesExpectedType: response.result.includes('number'),
      hidesValueFromResult: !response.result.includes(identifyingValue),
      hidesValueFromLogs: !logLines.join('\n').includes(identifyingValue),
      executorCalls,
    }).toEqual({
      namesPath: true,
      namesExpectedType: true,
      hidesValueFromResult: true,
      hidesValueFromLogs: true,
      executorCalls: 0,
    });
  });

  it('rejects an enum value and names the field and constraint', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'set_mode',
        description: 'Set operating mode',
        inputSchema: {
          type: 'object',
          properties: {mode: {type: 'string', enum: ['safe', 'fast']}},
          required: ['mode'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'set';
      }
    );

    const response = await registry.execute('set_mode', {mode: 'unsafe'});

    expect({
      executorCalls,
      namesField: response.result.includes('mode'),
      namesConstraint: /enum|allowed value/i.test(response.result),
    }).toEqual({executorCalls: 0, namesField: true, namesConstraint: true});
  });

  it('passes valid input with extra properties to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Berlin', units: 'celsius'};
    let executorCalls = 0;
    let passedInput: Record<string, unknown> | undefined;
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: locationInputSchema,
      },
      async receivedInput => {
        executorCalls += 1;
        passedInput = receivedInput;
        return 'sunny';
      }
    );

    await registry.execute('weather', input);

    expect({calls: executorCalls, input: passedInput}).toEqual({calls: 1, input});
  });

  it('validates each function-valued definition against its current schema', async () => {
    const registry = new ToolRegistry();
    const schemas = [
      {type: 'object', properties: {city: {type: 'string'}}, required: ['city']},
      {type: 'object', properties: {postalCode: {type: 'number'}}, required: ['postalCode']},
    ];
    let definitionCalls = 0;
    let executorCalls = 0;
    registry.register(
      () => ({
        name: 'dynamic_weather',
        description: 'Weather with a changing input schema',
        inputSchema: schemas[definitionCalls++ === 2 ? 1 : 0],
      }),
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const first = await registry.execute('dynamic_weather', {city: 'Berlin'});
    const second = await registry.execute('dynamic_weather', {postalCode: '10115'});

    expect({
      firstAccepted: first.result === 'sunny',
      secondNamesPath: second.result.includes('postalCode'),
      secondNamesExpectedType: second.result.includes('number'),
      executorCalls,
    }).toEqual({
      firstAccepted: true,
      secondNamesPath: true,
      secondNamesExpectedType: true,
      executorCalls: 1,
    });
  });

  it('throws at registration when a static schema is invalid and names the tool', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {name: 'broken_weather', description: 'Invalid schema', inputSchema: {type: 'not-a-json-schema-type'}},
        async () => 'sunny'
      )
    ).toThrow(/broken_weather/);
  });

  it('compiles a static schema once across repeated executions', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    registry.register(
      {name: 'weather', description: 'Get weather', inputSchema: locationInputSchema},
      async () => 'sunny'
    );
    const {calls: registrationCalls} = compile.mock;
    const compileCallsAfterRegistration = registrationCalls.length;

    for (let call = 0; call < 10; call += 1) {
      await registry.execute('weather', {location: 'Berlin'});
    }

    const {calls: executionCalls} = compile.mock;
    expect({compileCallsAfterRegistration, compileCallsAfterExecutions: executionCalls.length}).toEqual({
      compileCallsAfterRegistration: 1,
      compileCallsAfterExecutions: 1,
    });
  });
});
